const wholeMoney = (value) => Math.max(0, Math.round(Number(value) || 0));
// Los diálogos de confirmación viven dentro de cada módulo (no en el estado global de App),
// así que usamos una clase en <body> para poder ocultar el botón flotante mientras alguno esté abierto,
// sin tener que subir el estado de cada "pendingDelete" hasta la raíz.
let openDialogCount = 0;
// Si se pasa onRequestClose, además deja que el botón/gesto "atrás" del teléfono cierre el modal
// en vez de salir de la app: al abrirse, empuja una entrada de historial "de más"; al recibir
// popstate (atrás) la consume y cierra el diálogo. Si el diálogo se cierra por otro medio (botón
// Cancelar, X, guardar) sin haber recibido ese popstate, la limpieza saca esa entrada extra con
// history.back() para que la pila no crezca sin parar.
function useDialogOpenClass(onRequestClose) {
  useEffect(() => {
    openDialogCount++;
    document.body.classList.add("dialog-open");
    let pushed = false;
    let onPopState = null;
    if (onRequestClose) {
      window.history.pushState({ __modal: true }, "");
      pushed = true;
      onPopState = () => { pushed = false; onRequestClose(); };
      window.addEventListener("popstate", onPopState);
    }
    return () => {
      if (onPopState) window.removeEventListener("popstate", onPopState);
      openDialogCount = Math.max(0, openDialogCount - 1);
      if (openDialogCount === 0) document.body.classList.remove("dialog-open");
      // El history.back() de acá abajo también dispara un evento popstate (async) — sin este
      // aviso, el listener global de navegación entre módulos (que escucha el mismo evento en
      // toda la página) lo confundía con un "atrás" real del usuario y navegaba solo, cada vez
      // que se cerraba CUALQUIER modal por un botón normal (Cancelar, Guardar, detectar un
      // código, etc.), no solo con el gesto de atrás. window.__ogSuppressPopState en vez de una
      // variable de módulo porque GanttChart.jsx tiene su propia copia de este hook en otro
      // archivo y ambos escriben/leen la misma pila de historial del navegador.
      if (pushed) { window.__ogSuppressPopState = (window.__ogSuppressPopState || 0) + 1; window.history.back(); }
    };
  }, []);
}
// Un cliente puede tener varias plantas, cada una con su propio código (usado para numerar OTs).
