/* ===================================== Utils ===================================== */
function fileToImages(file) {
  return new Promise((resolve, reject) => {
    const rd = new FileReader();
    rd.onload = () => { const img = new Image(); img.onload = () => {
      const mk = (max, q) => { const s = Math.min(1, max / Math.max(img.width, img.height)); const w = Math.round(img.width * s), h = Math.round(img.height * s);
        const c = document.createElement("canvas"); c.width = w; c.height = h; c.getContext("2d").drawImage(img, 0, 0, w, h); return c.toDataURL("image/jpeg", q); };
      resolve({ report: mk(1600, 0.86), thumb: mk(320, 0.7) }); };
      img.onerror = reject; img.src = rd.result; };
    rd.onerror = reject; rd.readAsDataURL(file);
  });
}
// Foto de perfil: recorte cuadrado centrado y 256px de lado. Se recorta en vez de deformar porque
// el avatar es un círculo y la credencial un rectángulo vertical; una foto estirada se nota.
// El tamaño chico no es sólo estético: estas fotos viajan dentro de settings y el bootstrap devuelve
// todos los usuarios, así que el peso se multiplica por la nómina en cada arranque.
function fileToProfilePhoto(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        // Proporción 3:4 vertical, la de una foto carnet: es el marco de la credencial. Antes se
        // recortaba cuadrada y en un marco vertical habría quedado deformada o con bandas.
        const targetRatio = 3 / 4;
        let sw = image.width, sh = image.height;
        if (sw / sh > targetRatio) sw = sh * targetRatio; else sh = sw / targetRatio;
        const canvas = document.createElement("canvas");
        canvas.width = 240; canvas.height = 320;
        canvas.getContext("2d").drawImage(image, (image.width - sw) / 2, (image.height - sh) / 2, sw, sh, 0, 0, 240, 320);
        resolve(canvas.toDataURL("image/jpeg", 0.85));
      };
      image.onerror = reject; image.src = reader.result;
    };
    reader.onerror = reject; reader.readAsDataURL(file);
  });
}
// Firma escaneada: se reduce pero se conserva en PNG. fileToImages convierte a JPEG, que no admite
// transparencia y rellena de negro los píxeles transparentes — una firma recortada quedaba como un
// rectángulo negro. PNG mantiene el canal alfa y jsPDF lo respeta al insertarla en el remito.
function fileToSignature(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        const scale = Math.min(1, 600 / Math.max(image.width, image.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(image.width * scale));
        canvas.height = Math.max(1, Math.round(image.height * scale));
        // Sin fondo: el canvas arranca transparente y así se queda.
        canvas.getContext("2d").drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/png"));
      };
      image.onerror = reject; image.src = reader.result;
    };
    reader.onerror = reject; reader.readAsDataURL(file);
  });
}
function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const rd = new FileReader();
    rd.onload = () => resolve(rd.result);
    rd.onerror = reject;
    rd.readAsDataURL(file);
  });
}
const EVIDENCE_ACCEPT = "image/*,.pdf,application/pdf,.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,.csv,text/csv";
const MAX_DOCUMENT_BYTES = 5 * 1024 * 1024;
const MAX_MOVEMENT_DOCS = 8; // tiene que coincidir con MAX_MOVEMENT_ATTACHMENTS del servidor

function orderTotals(o) {
  const billedHours = billableLaborHours(o);
  const labor = o.laborBillable ? billedHours * (Number(o.technicians) || 1) * (Number(o.rate) || 0) : 0;
  const mats = (o.materials || []).filter((m) => m.billable).reduce((s, m) => s + (Number(m.qty) || 0) * (Number(m.price) || 0), 0);
  return { labor, mats, total: labor + mats, billedHours };
}
const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
function orderCosts(o) {
  const actualHours = (Number(o.laborHours) || 0) + (Math.max(0, Number(o.technical?.billableWaitMinutes) || 0) / 60);
  const labor = actualHours * (Number(o.technicians) || 1) * (Number(o.laborCost) || 0);
  const mats = (o.materials || []).reduce((s, m) => s + (Number(m.qty) || 0) * (Number(m.cost) || 0), 0);
  return { labor, mats, costTotal: labor + mats };
}
/* Avance de un presupuesto que se certifica por partes. Un presupuesto grande puede ejecutarse con
   varias órdenes de trabajo —la base ya lo admite: orders.budget_id no es única— pero hasta acá no
   había forma de ver cuánto se llevaba certificado ni cuánto quedaba.

   El número de certificación se calcula por orden de fecha en lugar de guardarse: así no hay campo
   que migrar y, sobre todo, no puede quedar desincronizado si se borra una orden del medio. */
const CERTIFIED_STATUSES = ["Completada", "Aprobada", "Facturada"];

function budgetProgress(budget, orders = []) {
  const linked = orders
    .filter((o) => (o.budgetId && o.budgetId === budget.id)
      || (budget.number && (o.quoteNumber === budget.number || o.budgetNumber === budget.number)))
    .sort((a, b) => String(a.date || a.createdAt || "").localeCompare(String(b.date || b.createdAt || "")));

  const items = linked.map((o, index) => ({
    id: o.id,
    seq: index + 1,
    date: o.date || "",
    status: o.status,
    total: orderTotals(o).total || 0,
    // "En proceso" y "Borrador" todavía no certifican nada: son trabajo comprometido, no ejecutado.
    counts: CERTIFIED_STATUSES.includes(o.status),
  }));

  const certified = items.filter((i) => i.counts).reduce((sum, i) => sum + i.total, 0);
  const inProgress = items.filter((i) => !i.counts).reduce((sum, i) => sum + i.total, 0);
  const amount = Math.max(0, Number(budget.amount) || 0);
  // Sin monto cargado no hay contra qué comparar: se informa lo certificado y nada más, en vez de
  // mostrar un 0% o un "infinito" que se leerían como un dato real.
  const pct = amount > 0 ? certified / amount : null;
  return {
    items,
    count: items.length,
    certified,
    inProgress,
    amount,
    pct,
    remaining: amount > 0 ? amount - certified : null,
    // El aviso mira lo certificado MÁS lo que ya está en curso: enterarse de que se pasó recién
    // cuando la última orden se aprobó llega tarde para hacer algo al respecto.
    over: amount > 0 && certified > amount,
    willExceed: amount > 0 && certified <= amount && certified + inProgress > amount,
  };
}

function orderMargin(o) {
  const rev = orderTotals(o).total, cost = orderCosts(o).costTotal;
  return { rev, cost, margin: rev - cost, pct: rev ? (rev - cost) / rev : 0 };
}
// Separador de las exportaciones CSV. Excel en español usa punto y coma como separador de lista:
// con comas abre todo el archivo en una sola columna, que es como venían saliendo estos reportes.
// Todos los valores se exportan entrecomillados, así que un ";' dentro de un texto no rompe nada.
const CSV_SEP = ";";
function downloadFile(name, text) {
  try { const blob = new Blob(["\ufeff" + text], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1500);
  } catch { alert("La descarga no está disponible en este navegador."); }
}
// Descarga un adjunto guardado como data: URI (imagen o PDF). Se pasa por Blob porque un <a download>
// apuntando directo a un data: URI largo falla en varios navegadores.
function downloadDataUrl(name, dataUrl) {
  try {
    const [meta, base64] = String(dataUrl || "").split(",");
    if (!base64) return false;
    const mime = (meta.match(/data:([^;]+)/) || [])[1] || "application/octet-stream";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
    const link = document.createElement("a");
    link.href = url; link.download = name; link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    return true;
  } catch { return false; }
}
// Un movimiento puede tener varios documentos (factura + cupón + remito). Los registros viejos
// guardan uno solo suelto; esta función unifica ambos formatos para el resto de la app.
const attachmentsOf = (movement) => {
  if (Array.isArray(movement?.attachments) && movement.attachments.length) return movement.attachments;
  return movement?.attachmentUrl ? [{ url: movement.attachmentUrl, name: movement.attachmentName || "Comprobante" }] : [];
};
const attachmentCountOf = (movement) => (Number.isFinite(movement?.attachmentCount) ? movement.attachmentCount : attachmentsOf(movement).length);
// Nombre de archivo trazable: empieza por el id del movimiento para que, al bajar varios juntos,
// se pueda saber a cuál corresponde cada uno sin abrirlos.
const receiptFileName = (movementId, attachment, index = 0, total = 1) => {
  const mime = (String(attachment?.url || "").match(/data:([^;]+)/) || [])[1] || "";
  const ext = mime.includes("pdf") ? "pdf" : mime.includes("png") ? "png" : mime.includes("image") ? "jpg" : "bin";
  const base = String(attachment?.name || "comprobante").replace(/\.[a-z0-9]{2,5}$/i, "").replace(/[\\/:*?"<>|]+/g, "-").trim();
  const suffix = total > 1 ? `_${index + 1}` : "";
  return `${movementId}${suffix}_${base || "comprobante"}.${ext}`;
};
// Parser del aviso de pago del cliente (formato ACH: Documento / Su documento / Fecha /
// Deducciones / Importe bruto). El PDF trae el texto embebido, así que los importes salen exactos
// en vez de reconocidos por OCR.
const parseArNumber = (text) => {
  const clean = String(text || "").replace(/\./g, "").replace(",", ".").replace(/[^\d.-]/g, "");
  const value = Number(clean);
  return Number.isFinite(value) ? value : 0;
};
// Se comparan los últimos 8 dígitos: el aviso del cliente y el sistema escriben el punto de venta
// distinto ("00004A00000118" vs "0004-00000118"), pero el número de comprobante es el mismo.
const receiptKey = (value) => { const digits = String(value || "").replace(/\D/g, ""); return digits.length >= 8 ? digits.slice(-8) : digits; };
function parsePaymentAdvice(text) {
  const rows = [];
  let total = null;
  String(text || "").split("\n").forEach((line) => {
    const clean = line.trim();
    if (/^total\s+general/i.test(clean)) {
      const numbers = clean.match(/[\d.]+,\d{2}/g) || [];
      if (numbers.length >= 2) total = { deductions: parseArNumber(numbers[numbers.length - 2]), gross: parseArNumber(numbers[numbers.length - 1]) };
      return;
    }
    // documento · su documento · fecha · deducciones · importe bruto
    const match = clean.match(/^(\S+)\s+(\S+)\s+(\d{2}[./-]\d{2}[./-]\d{4})\s+([\d.]*\d,\d{2})\s+([\d.]*\d,\d{2})$/);
    if (!match) return;
    rows.push({ document: match[1], receipt: match[2], date: match[3], deductions: parseArNumber(match[4]), gross: parseArNumber(match[5]) });
  });
  return { rows, total };
}
// Texto plano de una descripción con formato, para buscar y para resúmenes. Sin esto, buscar
// "span" o "color" traía tareas por sus etiquetas HTML en lugar de por su contenido.
const plainText = (html) => String(html || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
const initials = (n) => (n || "?").split(" ").map((x) => x[0]).slice(0, 2).join("").toUpperCase();
const localDateKey = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const localMonthKey = (date = new Date()) => localDateKey(date).slice(0, 7);
const todayStr = () => localDateKey();
const dateKey = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const addCalendarDays = (date, days) => { const next = new Date(date); next.setDate(next.getDate() + days); return next; };
// Días laborables entre dos fechas (inclusive): lunes a viernes cuentan como día completo,
// sábado cuenta medio día (solo mediodía) y domingo no cuenta.
const businessDaysBetween = (startStr, endStr) => {
  if (!startStr || !endStr) return 0;
  const start = new Date(`${startStr}T00:00:00`);
  const end = new Date(`${endStr}T00:00:00`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end < start) return 0;
  let total = 0;
  for (let cursor = new Date(start); cursor <= end; cursor = addCalendarDays(cursor, 1)) {
    const day = cursor.getDay(); // 0 domingo, 6 sábado
    if (day === 0) continue;
    total += day === 6 ? 0.5 : 1;
  }
  return total;
};
const startOfCalendarWeek = (date) => addCalendarDays(date, -((date.getDay() + 6) % 7));
// Roles cuyo acceso a proyectos se limita por la lista de "Accesos del proyecto". El servidor ya
// aplica este mismo criterio (isProjectScoped), así que ambos necesitan poder asignarse proyectos.
const isTecRole = (role) => role === "tecnico" || role === "tecnico_oficina";
const isOverdue = (t) => t.due && t.due < todayStr() && t.status !== "Hecho";
// Vence en los próximos N días (por defecto 2), sin contar las que ya están vencidas.
const isDueSoon = (t, days = 4) => t.due && t.status !== "Hecho" && t.due >= todayStr() && t.due <= localDateKey(addCalendarDays(new Date(), days));
// Urgencia de un proyecto calculada a partir de sus tareas (vencidas / por vencer), en vez de un campo
// manual de prioridad: así no depende de que alguien la actualice y siempre refleja el estado real.
// Ordena los proyectos como árbol —cada padre seguido de los suyos— y anota la profundidad para
// poder sangrar el selector. Un parentId que apunte a un proyecto inexistente o filtrado de la
// lista se trata como raíz, y al final se agregan los que un ciclo heredado de datos viejos hubiera
// dejado fuera: el selector nunca debe perder un proyecto por un vínculo mal formado.
const projectTree = (projects) => {
  const ids = new Set(projects.map((p) => p.id));
  const byParent = new Map();
  projects.forEach((p) => {
    const parent = p.parentId && p.parentId !== p.id && ids.has(p.parentId) ? p.parentId : null;
    if (!byParent.has(parent)) byParent.set(parent, []);
    byParent.get(parent).push(p);
  });
  const out = [], seen = new Set();
  const walk = (parent, depth) => (byParent.get(parent) || []).forEach((p) => {
    if (seen.has(p.id)) return;
    seen.add(p.id); out.push({ project: p, depth });
    walk(p.id, depth + 1);
  });
  walk(null, 0);
  projects.forEach((p) => { if (!seen.has(p.id)) { seen.add(p.id); out.push({ project: p, depth: 0 }); } });
  return out;
};

// Un proyecto junto con todo lo que cuelga de él. Elegir un "Proyecto General" tiene que mostrar
// también las tareas de sus subproyectos: si no, el general aparecería siempre vacío, que es
// justamente lo que la jerarquía viene a resolver.
const projectWithDescendants = (projects, rootId) => {
  const ids = new Set([rootId]);
  for (let grew = true; grew;) {
    grew = false;
    projects.forEach((p) => { if (p.parentId && ids.has(p.parentId) && !ids.has(p.id)) { ids.add(p.id); grew = true; } });
  }
  return ids;
};

// El alcance puede ser el id de un proyecto o un Set con el proyecto y sus subproyectos: un
// "Proyecto General" tiene que sumar lo que cuelga de él, no figurar siempre en cero.
const projectUrgency = (tasks, scope) => {
  const inScope = scope instanceof Set ? (t) => scope.has(t.project) : (t) => t.project === scope;
  const ts = tasks.filter(inScope);
  return { overdue: ts.filter(isOverdue).length, dueSoon: ts.filter(isDueSoon).length };
};
const dueLabel = (due) => {
  if (!due) return "Sin fecha";
  const today = new Date(`${todayStr()}T12:00:00`);
  const target = new Date(`${due}T12:00:00`);
  const days = Math.round((target - today) / 86400000);
  if (days === 0) return "Hoy";
  if (days === 1) return "Mañana";
  if (days === -1) return "Venció ayer";
  if (days < 0) return `Venció hace ${Math.abs(days)} días`;
  return target.toLocaleDateString("es-AR", { day: "2-digit", month: "short" });
};
const daysSince = (iso) => { if (!iso) return 0; return Math.floor((Date.now() - new Date(iso).getTime()) / 86400000); };
const STALE_DAYS = 4; // días sin cambios para marcar "estancada"
const WIP_LIMITS = { "En progreso": 5, "En revisión": 3 }; // límites de trabajo en curso por columna
const isStale = (t) => t.status !== "Hecho" && daysSince(t._updatedAt) >= STALE_DAYS;
const readPreference = (key, fallback) => { try { return { ...fallback, ...JSON.parse(localStorage.getItem(key) || "{}") }; } catch { return fallback; } };
const tenantPreferenceKey = (base, user) => `${base}:${user?.organizationId || "unknown"}:${user?.id || "anonymous"}`;
const deviceLabel = () => {
  if (typeof navigator === "undefined") return "esta computadora";
  if (typeof navigator.userAgentData?.mobile === "boolean") return navigator.userAgentData.mobile ? "este teléfono" : "esta computadora";
  return /Android.+Mobile|iPhone|iPod|Windows Phone|IEMobile|Opera Mini|webOS|BlackBerry/i.test(navigator.userAgent || "") ? "este teléfono" : "esta computadora";
};
const dateTimeLocalValue = (value) => {
  if (!value) return "";
  const date = new Date(value); if (Number.isNaN(date.getTime())) return String(value).slice(0, 16);
  const offset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
};
const isoFromLocal = (value) => value ? new Date(value).toISOString() : "";
const timelineWorkMs = (technical, now = Date.now()) => {
  const sessions = Array.isArray(technical?.workSessions) ? technical.workSessions : [];
  if (sessions.length) return sessions.reduce((total, session) => {
    const start = new Date(session.start).getTime(); const end = session.end ? new Date(session.end).getTime() : now;
    return total + (Number.isFinite(start) && Number.isFinite(end) ? Math.max(0, end - start) : 0);
  }, 0);
  const start = technical?.startedAt ? new Date(technical.startedAt).getTime() : NaN;
  const end = technical?.completedAt ? new Date(technical.completedAt).getTime() : now;
  return Number.isFinite(start) && Number.isFinite(end) ? Math.max(0, end - start) : 0;
};
const timelineErrors = (technical, now = Date.now()) => {
  const errors = [];
  const points = [["aviso", technical?.reportedAt], ["llegada", technical?.arrivalAt], ["inicio", technical?.startedAt], ["finalización", technical?.completedAt]]
    .filter(([, value]) => value)
    .map(([label, value]) => [label, new Date(value).getTime()]);
  for (let index = 1; index < points.length; index += 1) {
    if (!Number.isFinite(points[index - 1][1]) || !Number.isFinite(points[index][1]) || points[index][1] < points[index - 1][1]) {
      errors.push(`La ${points[index][0]} no puede ser anterior al ${points[index - 1][0]}.`);
    }
  }
  const arrival = technical?.arrivalAt ? new Date(technical.arrivalAt).getTime() : NaN;
  const end = technical?.completedAt ? new Date(technical.completedAt).getTime() : now;
  if (Number.isFinite(arrival) && Number.isFinite(end) && end >= arrival) {
    const onSiteMinutes = Math.max(1, Math.ceil((end - arrival) / 60000));
    const effectiveMinutes = Math.ceil(timelineWorkMs(technical, end) / 60000);
    if (effectiveMinutes > onSiteMinutes) errors.push(`El tiempo efectivo (${effectiveMinutes} min) supera el tiempo total en planta (${onSiteMinutes} min). Revisa los horarios.`);
    const waitMinutes = Number(technical?.billableWaitMinutes) || 0;
    if (waitMinutes > onSiteMinutes) errors.push(`La espera registrada (${waitMinutes} min) supera el tiempo total en planta (${onSiteMinutes} min). Revisa la llegada, la finalización o la espera.`);
  }
  if ((Number(technical?.billableWaitMinutes) || 0) > 0 && !technical?.billableWaitReason?.trim()) errors.push("Indica el motivo de la espera por condiciones del sitio.");
  return errors;
};
// Mínimo facturable de una visita corta. Sale del contrato del cliente cuando la orden tiene uno
// (el servidor le copia minimumBillableHours); 2 h para las que no. Se cambia SOLO el valor del
// mínimo, no cuándo se aplica: la regla sigue siendo "visita de menos de 1 hora", como estaba.
const billableLaborHours = billableHoursValue;
const compactDuration = (milliseconds) => {
  const minutes = Math.max(0, Math.round((Number(milliseconds) || 0) / 60000));
  return `${Math.floor(minutes / 60)} h ${String(minutes % 60).padStart(2, "0")} min`;
};

// Recharts identifica sus propias piezas (Bar, Pie) buscando un método estático
// (getComposedData) en el `type` de cada elemento hijo dentro de <BarChart>/<PieChart>. Envolver
// <Bar>/<Pie> en un componente propio (como se hacía antes, solo para inyectar animationDuration
// según prefers-reduced-motion) cambia ese `type` a una función sin ese estático: Recharts no logra
// calcular la geometría de la serie y las barras/porciones dejan de dibujarse, aunque ejes y grilla
// (que no dependen de ese estático) se vean normales. Por eso acá NO se envuelve: se reutiliza la
// clase real de Recharts y sólo se le pisan los defaultProps de animación.
const applyReducedMotionDefaults = () => {
  const reduced = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  RechartsBar.defaultProps = { ...RechartsBar.defaultProps, isAnimationActive: !reduced, animationDuration: 550, animationEasing: "ease-out" };
  RechartsPie.defaultProps = { ...RechartsPie.defaultProps, isAnimationActive: !reduced, animationDuration: 550, animationEasing: "ease-out" };
};
applyReducedMotionDefaults();
if (typeof window !== "undefined") window.matchMedia("(prefers-reduced-motion: reduce)").addEventListener?.("change", applyReducedMotionDefaults);
const Bar = RechartsBar;
const Pie = RechartsPie;

/* Momento de un aviso, en corto. Hoy se muestra la hora y los días anteriores la fecha: dos
   resúmenes diarios seguidos suelen decir lo mismo, y sin esto parecen el mismo aviso duplicado. */
function notifWhen(at) {
  if (!at) return "";
  const fecha = new Date(at);
  if (Number.isNaN(fecha.getTime())) return "";
  const hoy = new Date();
  const mismoDia = fecha.toDateString() === hoy.toDateString();
  const ayer = new Date(hoy); ayer.setDate(ayer.getDate() - 1);
  if (mismoDia) return "Hoy " + fecha.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  if (fecha.toDateString() === ayer.toDateString()) return "Ayer " + fecha.toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit", hour12: false });
  return fecha.toLocaleDateString("es-AR", { day: "2-digit", month: "short" });
}

