  const ars = (value) => `ARS ${(Number(value) || 0).toLocaleString("es-AR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const rate = Number(wholesaleQuote?.arsPerUsd) || 0;
